package com.nexus.property.comparison;
import com.nexus.property.auth.*;import com.nexus.property.core.*;import com.nexus.property.property.PropertyMapper;import jakarta.servlet.http.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping({"/api/comparisons","/api/customer/comparisons"}) public class ComparisonController{private final Db db;public ComparisonController(Db db){this.db=db;}private CurrentUser user(HttpServletRequest r){return AuthFilter.role(r,"CUSTOMER","ADMIN");}private Map<String,Object> one(String id,String uid){var c=db.one("SELECT * FROM property_comparisons WHERE id=? AND customer_id=?",id,uid);if(c==null)throw Api.error(404,"Comparison not found.");var props=db.all("SELECT p.*,u.full_name owner_name,u.email owner_email,u.phone owner_phone,(SELECT url FROM property_images WHERE property_id=p.id ORDER BY is_primary DESC,display_order LIMIT 1) primary_image,(SELECT AVG(score) FROM ratings WHERE property_id=p.id) avg_score,(SELECT COUNT(*) FROM ratings WHERE property_id=p.id) rating_count FROM comparison_items ci JOIN properties p ON p.id=ci.property_id JOIN users u ON u.id=p.owner_id WHERE ci.comparison_id=? ORDER BY ci.position,ci.created_at",id).stream().map(PropertyMapper::map).toList();return new LinkedHashMap<>(Map.of("id",id,"name",Rows.s(c,"name"),"properties",props,"createdAt",Rows.l(c,"created_at"),"updatedAt",Rows.l(c,"updated_at")));}@GetMapping public Map<String,Object>list(HttpServletRequest r){var u=user(r);var x=db.all("SELECT * FROM property_comparisons WHERE customer_id=? ORDER BY updated_at DESC",u.userId()).stream().map(c->one(Rows.s(c,"id"),u.userId())).toList();return Api.ok("Comparisons retrieved.",x);}@PostMapping @ResponseStatus(HttpStatus.CREATED)public Map<String,Object>create(HttpServletRequest r,@RequestBody Map<String,Object>b){var u=user(r);String id=db.uuid();long n=System.currentTimeMillis();db.exec("INSERT INTO property_comparisons(id,customer_id,name,created_at,updated_at) VALUES(?,?,?,?,?)",id,u.userId(),Objects.toString(b.getOrDefault("name","My Comparison")),n,n);return Api.ok("Comparison created.",one(id,u.userId()));}@GetMapping("/property-ids")public Map<String,Object>ids(HttpServletRequest r){var u=user(r);var a=db.all("SELECT DISTINCT ci.property_id FROM comparison_items ci JOIN property_comparisons c ON c.id=ci.comparison_id WHERE c.customer_id=?",u.userId()).stream().map(x->Rows.s(x,"property_id")).toList();return Api.ok(a);}@PostMapping("/quick-add")public Map<String,Object>quick(HttpServletRequest r,@RequestBody Map<String,Object>b){var u=user(r);String pid=Objects.toString(b.get("propertyId"),"");var c=db.one("SELECT id FROM property_comparisons WHERE customer_id=? ORDER BY updated_at DESC LIMIT 1",u.userId());String cid;if(c==null){cid=db.uuid();long n=System.currentTimeMillis();db.exec("INSERT INTO property_comparisons(id,customer_id,name,created_at,updated_at) VALUES(?,?,?,?,?)",cid,u.userId(),"My Comparison",n,n);}else cid=Rows.s(c,"id");add(cid,pid);return Api.ok("Property added to comparison.",one(cid,u.userId()));}@GetMapping("/{id}")public Map<String,Object>get(HttpServletRequest r,@PathVariable String id){var u=user(r);return Api.ok("Comparison retrieved.",one(id,u.userId()));}@PutMapping("/{id}")public Map<String,Object>rename(HttpServletRequest r,@PathVariable String id,@RequestBody Map<String,Object>b){var u=user(r);db.exec("UPDATE property_comparisons SET name=?,updated_at=? WHERE id=? AND customer_id=?",b.get("name"),System.currentTimeMillis(),id,u.userId());return Api.ok("Comparison updated.",one(id,u.userId()));}@DeleteMapping("/{id}")public Map<String,Object>del(HttpServletRequest r,@PathVariable String id){var u=user(r);db.exec("DELETE FROM property_comparisons WHERE id=? AND customer_id=?",id,u.userId());return Api.message("Comparison deleted.");}@PostMapping("/{id}/properties")public Map<String,Object>addP(HttpServletRequest r,@PathVariable String id,@RequestBody Map<String,Object>b){var u=user(r);one(id,u.userId());add(id,Objects.toString(b.get("propertyId"),""));return Api.ok("Property added.",one(id,u.userId()));}@DeleteMapping("/{id}/properties/{propertyId}")public Map<String,Object>remove(HttpServletRequest r,@PathVariable String id,@PathVariable String propertyId){var u=user(r);one(id,u.userId());db.exec("DELETE FROM comparison_items WHERE comparison_id=? AND property_id=?",id,propertyId);db.exec("UPDATE property_comparisons SET updated_at=? WHERE id=?",System.currentTimeMillis(),id);return Api.ok("Property removed.",one(id,u.userId()));}private void add(String cid,String pid){if(db.one("SELECT id FROM comparison_items WHERE comparison_id=? AND property_id=?",cid,pid)==null){long pos=db.scalarLong("SELECT COUNT(*) FROM comparison_items WHERE comparison_id=?",cid);if(pos>=4)throw Api.error(400,"A comparison can contain up to 4 properties.");db.exec("INSERT INTO comparison_items(id,comparison_id,property_id,position,created_at) VALUES(?,?,?,?,?)",db.uuid(),cid,pid,pos,System.currentTimeMillis());db.exec("UPDATE property_comparisons SET updated_at=? WHERE id=?",System.currentTimeMillis(),cid);}}}
